  /// See https://easings.net/.
  @ffi.Float()
  external double c1;

  /// The c2 variable of easing functions.
  ///
  /// See https://easings.net/.
  @ffi.Float()
  external double c2;

  /// The c3 variable of easing functions.
  ///
  /// See https://easings.net/.
  @ffi.Float()
  external double c3;

  /// The c4 variable of easing functions.
