  /// The n1 variable of easing functions.
  ///
  /// See https://easings.net/.
  @ffi.Float()
  external double n1;

  /// The d1 variable of easing functions.
  ///
  /// See https://easings.net/.
  @ffi.Float()
  external double d1;
}

